cssText:
/* ---- prompt submit button: accent-colored, empty -> filled states -------- */
[data-action="prompt-submit"]{
  background: color-mix(in srgb, var(--color-v2-text-text-accent, #38bdf8) 10%, transparent) !important;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--color-v2-text-text-accent, #38bdf8) 32%, transparent) !important;
  opacity: 1 !important;
  transition: background-color .18s ease, box-shadow .18s ease, transform .12s ease !important;
}
[data-action="prompt-submit"] [data-slot="icon-svg"]{
  color: color-mix(in srgb, var(--color-v2-text-text-accent, #38bdf8) 72%, transparent) !important;
  transition: color .18s ease !important;
}
[data-action="prompt-submit"]:not(:disabled){
  background: var(--color-v2-text-text-accent, #38bdf8) !important;
  box-shadow: none !important;
}
[data-action="prompt-submit"]:not(:disabled) [data-slot="icon-svg"]{
  color: #06283b !important;
}
[data-action="prompt-submit"]:not(:disabled):hover{
  filter: brightness(1.08) !important;
}
[data-action="prompt-submit"]:not(:disabled):active{
  transform: scale(.94) !important;
}
